package devicekey_test

// Interop tests for device signature verification.
//
// The vectors below were generated OUTSIDE Go, because a Go test that signs with
// Go and verifies with Go proves only that Go is self-consistent. It would not
// catch the one bug this file exists to prevent: a signature that is valid and
// always fails verification because the encoding is wrong.
//
//   publicKey  — generated by WebCrypto (ECDSA P-256), exported as SPKI
//   derB64     — signed by OpenSSL with dsaEncoding = der, which is what a
//                BROWSER produces, so this vector represents the real client
//   p1363B64   — signed by Node's WebCrypto, which emits raw r||s instead of
//                DER. Embedded deliberately: see the package comment.

import (
	"crypto/ecdsa"
	"crypto/elliptic"
	"crypto/rand"
	"crypto/sha256"
	"crypto/x509"
	"encoding/base64"
	"encoding/hex"
	"errors"
	"strings"
	"testing"

	"github.com/mikedalu/phc-records/api/internal/platform/devicekey"
)

// Fixed inputs shared with web/src/sync/deviceKey.ts.
const (
	vecPublicKey   = "MFkwEwYHKoZIzj0CAQYIKoZIzj0DAQcDQgAErXvV4mQzCmqUKQ3oPZC5O0DWvDktD8u0QcsGPjvoiBhzUvfRR0Sz4df7ZFY5hdhIsnm5_g0YrKmxZNKBMrWwbA"
	vecFingerprint = "746c91ed971d55d95340608c8dd4e63d5dfd3ffa2cd8781b7ebc21660d7e210f"
	vecDER         = "MEYCIQDHoHV2w1uDJyGmDs7RkBvE5nPC35rBLTxYkL0fdEwgPQIhALrUbboe5Jfu6u42136t9rWKFh1ec8xyJkkBIWun6DIj"
	vecP1363       = "XPup9KHF4ocp9q-8cNNDLHmKe0tdZGLv1BSTjeVXbrVLwPlLnCpA8SmWvB_9K6ATyWtgwCQLzDJzYF4IZr6OQQ"

	vecMethod    = "POST"
	vecPath      = "/api/v1/sync/push"
	vecDeviceID  = "018f3c2a-7b1e-7c3d-8f01-2a4b6c8d0e12"
	vecTimestamp = "2026-02-14T09:31:07.221Z"
	vecNonce     = "3q2-7wTkR9mZ1sVbQ0cJx4LpA6nH8yGd"
	vecBody      = `{"batchId":"018f3c2a-1111-7abc-8def-000000000001"}`

	// The exact string the client signed. Kept as a literal so a change in
	// CanonicalString fails here rather than in a browser console.
	vecCanonical = "POST\n/api/v1/sync/push\n018f3c2a-7b1e-7c3d-8f01-2a4b6c8d0e12\n" +
		"2026-02-14T09:31:07.221Z\n3q2-7wTkR9mZ1sVbQ0cJx4LpA6nH8yGd\n" +
		"JpJ8PfffnsoqzS1c581ZDod4K56omTvncBS6MqRiAUQ"
)

func mustVerifier(t *testing.T, encoded string) *ecdsa.PublicKey {
	t.Helper()
	pub, _, err := devicekey.ParsePublicKey(encoded)
	if err != nil {
		t.Fatalf("parse public key: %v", err)
	}
	return pub
}

// TestCanonicalStringMatchesClient is the highest-value test in this file.
//
// If this fails, every signature in production fails, and the symptom looks
// exactly like a broken key.
func TestCanonicalStringMatchesClient(t *testing.T) {
	got := devicekey.CanonicalString(
		vecMethod, vecPath, vecDeviceID, vecTimestamp, vecNonce, []byte(vecBody),
	)
	if got != vecCanonical {
		t.Fatalf("canonical string drifted from the client\n got: %q\nwant: %q", got, vecCanonical)
	}

	// Shape assertions, so a refactor that "tidies" this into five or seven
	// fields cannot pass by accident.
	if strings.Count(got, "\n") != 5 {
		t.Fatalf("expected 6 newline-separated fields, got %d newlines", strings.Count(got, "\n"))
	}
	if strings.HasSuffix(got, "\n") {
		t.Fatal("canonical string must not have a trailing newline")
	}
}

// TestVerifyDerVector is the browser path: WebCrypto/OpenSSL ASN.1 DER.
func TestVerifyDerVector(t *testing.T) {
	pub := mustVerifier(t, vecPublicKey)
	if err := devicekey.Verify(pub, []byte(vecCanonical), vecDER); err != nil {
		t.Fatalf("DER signature rejected: %v", err)
	}
}

// TestVerifyP1363Vector covers runtimes that emit raw r||s (Node WebCrypto,
// some WebViews). Without the fallback in Verify, these devices could never push.
func TestVerifyP1363Vector(t *testing.T) {
	pub := mustVerifier(t, vecPublicKey)

	raw, err := base64.RawURLEncoding.DecodeString(vecP1363)
	if err != nil {
		t.Fatalf("decode p1363 vector: %v", err)
	}
	if len(raw) != 64 {
		t.Fatalf("p1363 vector should be 64 bytes, got %d", len(raw))
	}

	if err := devicekey.Verify(pub, []byte(vecCanonical), vecP1363); err != nil {
		t.Fatalf("P1363 signature rejected: %v", err)
	}
}

func TestVerifyRejectsTamperedMessage(t *testing.T) {
	pub := mustVerifier(t, vecPublicKey)

	tampered := strings.Replace(vecCanonical, vecDeviceID, "018f3c2a-0000-7000-8000-000000000000", 1)
	if tampered == vecCanonical {
		t.Fatal("test setup is broken: tampering changed nothing")
	}

	for name, sig := range map[string]string{"der": vecDER, "p1363": vecP1363} {
		if err := devicekey.Verify(pub, []byte(tampered), sig); !errors.Is(err, devicekey.ErrInvalidSignature) {
			t.Fatalf("%s: expected ErrInvalidSignature for a modified message, got %v", name, err)
		}
	}
}

func TestVerifyRejectsWrongKey(t *testing.T) {
	// A key generated here is fine for a REJECTION test: we are proving the
	// signature does not verify, not that the key parses.
	other, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		t.Fatalf("generate key: %v", err)
	}

	if err := devicekey.Verify(&other.PublicKey, []byte(vecCanonical), vecDER); !errors.Is(err, devicekey.ErrInvalidSignature) {
		t.Fatalf("expected rejection with an unrelated key, got %v", err)
	}
}

func TestVerifyRejectsGarbage(t *testing.T) {
	pub := mustVerifier(t, vecPublicKey)

	cases := map[string]string{
		"empty":         "",
		"not base64url": "!!!not base64!!!",
		"truncated der": vecDER[:20],
		"random bytes":  "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA",
		"over long":     strings.Repeat("A", devicekey.MaxSignatureChars+1),
	}

	for name, sig := range cases {
		if err := devicekey.Verify(pub, []byte(vecCanonical), sig); err == nil {
			t.Fatalf("%s: expected rejection, got nil", name)
		}
	}
}

func TestParsePublicKeyRejectsBadInput(t *testing.T) {
	p384, err := ecdsa.GenerateKey(elliptic.P384(), rand.Reader)
	if err != nil {
		t.Fatalf("generate p384: %v", err)
	}
	p384DER, err := x509.MarshalPKIXPublicKey(&p384.PublicKey)
	if err != nil {
		t.Fatalf("marshal p384: %v", err)
	}

	cases := map[string]string{
		"empty":               "",
		"invalid base64":      "!!!",
		"valid b64, garbage":  base64.RawURLEncoding.EncodeToString([]byte("this is not a key")),
		"wrong curve (P-384)": base64.RawURLEncoding.EncodeToString(p384DER),
		"too long":            strings.Repeat("A", devicekey.MaxPublicKeyChars+1),
	}

	for name, encoded := range cases {
		if _, _, err := devicekey.ParsePublicKey(encoded); !errors.Is(err, devicekey.ErrInvalidKey) {
			t.Fatalf("%s: expected ErrInvalidKey, got %v", name, err)
		}
	}
}

func TestFingerprintIsSHA256OfDER(t *testing.T) {
	_, der, err := devicekey.ParsePublicKey(vecPublicKey)
	if err != nil {
		t.Fatalf("parse: %v", err)
	}

	if got := devicekey.Fingerprint(der); got != vecFingerprint {
		t.Fatalf("fingerprint changed: got %s want %s", got, vecFingerprint)
	}

	// Sanity: it really is the SHA-256 of the decoded bytes, not of the base64
	// text. Getting this wrong produces fingerprints that look fine and never
	// match what the client displays.
	sum := sha256.Sum256(der)
	if want := hex.EncodeToString(sum[:]); want != vecFingerprint {
		t.Fatalf("expected vector is not the sha256 of the DER: %s", want)
	}
}
